{"file_path":"src/parser.js","content":"import { ConfigError } from './errors.js'

const NAME_CHAR = /[A-Za-z0-9_-]/
const DIGITS = '\\d+(?:_\\d+)*'
const INT_RE = new RegExp(`^[+-]?${DIGITS}$`)
const FLOAT_RE = new RegExp(`^[+-]?${DIGITS}(?:\\.${DIGITS})?(?:[eE][+-]?${DIGITS})?$`)

function skipWs(s, p) {
  while (p < s.length && (s[p] === ' ' || s[p] === '\t')) p++
  return p
}

function cpCompare(a, b) {
  const ca = Array.from(a)
  const cb = Array.from(b)
  const len = Math.min(ca.length, cb.length)
  for (let i = 0; i < len; i++) {
    const x = ca[i].codePointAt(0)
    const y = cb[i].codePointAt(0)
    if (x !== y) return x - y
  }
  return ca.length - cb.length
}

function formatPath(parts) {
  let out = ''
  for (const p of parts) {
    if (p.type === 'index') out += `[${p.index}]`
    else out += (out === '' ? '' : '.') + p.name
  }
  return out
}

function parseStringLiteral(s, pos, lineNo) {
  const quote = s[pos]
  let p = pos + 1
  let out = ''
  if (quote === "'") {
    while (true) {
      if (p >= s.length) throw new ConfigError(lineNo, 'unterminated string')
      if (s[p] === "'") { p++; break }
      out += s[p]; p++
    }
  } else {
    while (true) {
      if (p >= s.length) throw new ConfigError(lineNo, 'unterminated string')
      const c = s[p]
      if (c === '"') { p++; break }
      if (c === '\\') {
        p++
        if (p >= s.length) throw new ConfigError(lineNo, 'unterminated string')
        const e = s[p]
        if (e === '"') { out += '"'; p++ }
        else if (e === '\\') { out += '\\'; p++ }
        else if (e === 'n') { out += '\n'; p++ }
        else if (e === 't') { out += '\t'; p++ }
        else if (e === 'r') { out += '\r'; p++ }
        else if (e === '0') { out += '\0'; p++ }
        else if (e === 'u') {
          const hex = s.slice(p + 1, p + 5)
          if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
            out += String.fromCharCode(parseInt(hex, 16))
            p += 5
          } else {
            throw new ConfigError(lineNo, 'invalid escape \\u')
          }
        } else {
          throw new ConfigError(lineNo, `invalid escape \\${e}`)
        }
      } else {
        out += c; p++
      }
    }
  }
  return { value: out, pos: p }
}

function parseBareword(s, pos) {
  let p = pos
  while (p < s.length && NAME_CHAR.test(s[p])) p++
  if (p > pos) return { text: s.slice(pos, p), pos: p }
  return null
}

function parseNameSegment(s, pos, lineNo) {
  if (pos < s.length && (s[pos] === '"' || s[pos] === "'")) {
    const r = parseStringLiteral(s, pos, lineNo)
    return { text: r.value, pos: r.pos }
  }
  return parseBareword(s, pos)
}

function parseDottedName(s, pos, lineNo, firstFailMsg) {
  const segments = []
  let p = pos
  let first = true
  while (true) {
    p = skipWs(s, p)
    const seg = parseNameSegment(s, p, lineNo)
    if (!seg) {
      throw new ConfigError(lineNo, first ? firstFailMsg : 'expected a name')
    }
    segments.push(seg.text)
    p = seg.pos
    first = false
    const afterWs = skipWs(s, p)
    if (afterWs < s.length && s[afterWs] === '.') {
      p = afterWs + 1
      continue
    }
    break
  }
  return { segments, pos: p }
}

function parseValueAt(s, pos, lineNo, pathPrefix) {
  const p0 = skipWs(s, pos)
  if (p0 >= s.length || s[p0] === '#' || s[p0] === ';') {
    throw new ConfigError(lineNo, 'expected a value')
  }
  const ch = s[p0]
  if (ch === '"' || ch === "'") {
    const r = parseStringLiteral(s, p0, lineNo)
    return { node: { kind: 'string', value: r.value }, pos: r.pos }
  }
  if (ch === '[') return parseArray(s, p0, lineNo, pathPrefix)
  if (ch === '{') return parseInlineTable(s, p0, lineNo, pathPrefix)
  let q = p0
  while (q < s.length && s[q] !== ' ' && s[q] !== '\t' && s[q] !== ',' && s[q] !== ']' && s[q] !== '}') q++
  const text = s.slice(p0, q)
  if (text === 'true') return { node: { kind: 'boolean', value: true }, pos: q }
  if (text === 'false') return { node: { kind: 'boolean', value: false }, pos: q }
  if (INT_RE.test(text)) return { node: { kind: 'integer', value: Number(text.replace(/_/g, '')) }, pos: q }
  if (FLOAT_RE.test(text)) return { node: { kind: 'float', value: Number(text.replace(/_/g, '')) }, pos: q }
  throw new ConfigError(lineNo, `invalid value ${text}`)
}

function parseArray(s, pos, lineNo, pathPrefix) {
  let p = pos + 1
  const items = []
  let idx = 0
  while (true) {
    p = skipWs(s, p)
    if (p < s.length && s[p] === ']') { p++; return { node: { kind: 'array', items }, pos: p } }
    if (p >= s.length || s[p] === '#' || s[p] === ';') throw new ConfigError(lineNo, 'unterminated array')
    const r = parseValueAt(s, p, lineNo, pathPrefix.concat([{ type: 'index', index: idx }]))
    items.push(r.node)
    p = r.pos
    idx++
    p = skipWs(s, p)
    if (p < s.length && s[p] === ',') {
      p++
      p = skipWs(s, p)
      if (p < s.length && s[p] === ']') { p++; return { node: { kind: 'array', items }, pos: p } }
      continue
    }
    if (p < s.length && s[p] === ']') { p++; return { node: { kind: 'array', items }, pos: p } }
