function walkAndCreate(startTable, basePathParts, segments, lineNo) {
  let node = startTable
  const parts = basePathParts.slice()
  for (let idx = 0; idx < segments.length - 1; idx++) {
    const seg = segments[idx]
    parts.push({ type: 'key', name: seg })
    const child = node.map.get(seg)
    if (child === undefined) {
      const t = { kind: 'table', map: new Map(), explicit: false }
      node.map.set(seg, t)
      node = t
    } else if (child.kind === 'table') {
      node = child
    } else if (child.kind === 'aot') {
      const li = child.items.length - 1
      parts.push({ type: 'index', index: li })
      node = child.items[li]
    } else {
      throw new ConfigError(lineNo, `${formatPath(parts)} is not a table`)
    }
  }
  return { table: node, parts, lastSeg: segments[segments.length - 1] }
}

function assignInto(startTable, basePathParts, segments, lineNo, valueNode) {
  const { table, parts, lastSeg } = walkAndCreate(startTable, basePathParts, segments, lineNo)
  const finalParts = parts.concat([{ type: 'key', name: lastSeg }])
  const existing = table.map.get(lastSeg)
  if (existing !== undefined) {
    throw new ConfigError(lineNo, `key ${formatPath(finalParts)} is defined twice`)
  }
  table.map.set(lastSeg, valueNode)
  return finalParts
}

function parseInlineTable(s, pos, lineNo, pathPrefix) {
  let p = pos + 1
  const table = { kind: 'table', map: new Map(), explicit: false }
  p = skipWs(s, p)
  if (p < s.length && s[p] === '}') { p++; return { node: table, pos: p } }
  while (true) {
    p = skipWs(s, p)
    if (p >= s.length || s[p] === '#' || s[p] === ';') throw new ConfigError(lineNo, 'unterminated inline table')
    const { segments, pos: afterName } = parseDottedName(s, p, lineNo, 'expected a name')
    p = skipWs(s, afterName)
    if (!(p < s.length && s[p] === '=')) throw new ConfigError(lineNo, 'expected = in an inline table')
    p++
    const { table: destTable, parts, lastSeg } = walkAndCreate(table, pathPrefix, segments, lineNo)
    const finalParts = parts.concat([{ type: 'key', name: lastSeg }])
    const r = parseValueAt(s, p, lineNo, finalParts)
    const existing = destTable.map.get(lastSeg)
    if (existing !== undefined) throw new ConfigError(lineNo, `key ${formatPath(finalParts)} is defined twice`)
    destTable.map.set(lastSeg, r.node)
    p = r.pos
    p = skipWs(s, p)
    if (p < s.length && s[p] === '}') { p++; return { node: table, pos: p } }
    if (p < s.length && s[p] === ',') { p++; continue }
    throw new ConfigError(lineNo, 'unterminated inline table')
  }
}

function processHeader(line, pos, lineNo, state) {
  let p = pos + 1
  let isAot = false
  if (p < line.length && line[p] === '[') { isAot = true; p++ }
  p = skipWs(line, p)
  const { segments, pos: afterName } = parseDottedName(line, p, lineNo, 'expected a name')
  p = skipWs(line, afterName)
  if (isAot) {
    if (!(p < line.length && line[p] === ']' && p + 1 < line.length && line[p + 1] === ']')) {
      throw new ConfigError(lineNo, 'unterminated table header')
    }
    p += 2
  } else {
    if (!(p < line.length && line[p] === ']')) {
      throw new ConfigError(lineNo, 'unterminated table header')
    }
    p += 1
  }
  p = skipWs(line, p)
  if (p < line.length && line[p] !== '#' && line[p] !== ';') {
    throw new ConfigError(lineNo, 'trailing text after a table header')
  }
  if (isAot) applyAotHeader(segments, lineNo, state)
  else applyTableHeader(segments, lineNo, state)
}

function applyTableHeader(segments, lineNo, state) {
  const { table, parts, lastSeg } = walkAndCreate(state.root, [], segments, lineNo)
  const finalParts = parts.concat([{ type: 'key', name: lastSeg }])
  const existing = table.map.get(lastSeg)
  if (existing === undefined) {
    const t = { kind: 'table', map: new Map(), explicit: true }
    table.map.set(lastSeg, t)
    state.currentTable = t
    state.currentTablePath = finalParts
  } else if (existing.kind === 'table') {
    if (existing.explicit) throw new ConfigError(lineNo, `table ${formatPath(finalParts)} is defined twice`)
    existing.explicit = true
    state.currentTable = existing
    state.currentTablePath = finalParts
  } else {
    throw new ConfigError(lineNo, `${formatPath(finalParts)} is not a table`)
  }
}

function applyAotHeader(segments, lineNo, state) {
  const { table, parts, lastSeg } = walkAndCreate(state.root, [], segments, lineNo)
  const finalParts = parts.concat([{ type: 'key', name: lastSeg }])
  const existing = table.map.get(lastSeg)
  let aot
  if (existing === undefined) {
    aot = { kind: 'aot', items: [] }
    table.map.set(lastSeg, aot)
  } else if (existing.kind === 'aot') {
    aot = existing
  } else {
    throw new ConfigError(lineNo, `${formatPath(finalParts)} is not an array of tables`)
  }
  const t = { kind: 'table', map: new Map(), explicit: true }
  aot.items.push(t)
  state.currentTable = t
  state.currentTablePath = finalParts.concat([{ type: 'index', index: aot.items.length - 1 }])
}

function processAssignment(line, pos, lineNo, state) {
  const { segments, pos: afterName } = parseDottedName(line, pos, lineNo, 'expected key = value')
  let p = skipWs(line, afterName)
  if (!(p < line.length && line[p] === '=')) throw new ConfigError(lineNo, 'expected key = value')
  p++
  const pathPrefix = state.currentTablePath.concat(segments.map(name => ({ type: 'key', name })))
  const r = parseValueAt(line, p, lineNo, pathPrefix)
  p = skipWs(line, r.pos)
  if (p < line.length && line[p] !== '#' && line[p] !== ';') {
    throw new ConfigError(lineNo, 'trailing text after a value')
  }
  assignInto(state.currentTable, state.currentTablePath, segments, lineNo, r.node)
}

function processLine(line, lineNo, state) {
  let i = 0
  while (i < line.length && (line[i] === ' ' || line[i] === '\t')) i++
  if (i >= line.length) return
  if (line[i] === '#' || line[i] === ';') return
  if (line[i] === '[') processHeader(line, i, lineNo, state)
  else processAssignment(line, i, lineNo, state)
}

export function parseDocument(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const root = { kind: 'table', map: new Map(), explicit: true }
  const state = { root, currentTable: root, currentTablePath: [] }
  for (let idx = 0; idx < lines.length; idx++) {
    processLine(lines[idx], idx + 1, state)
  }
  return root
}

export { cpCompare }
