{"file_path":"src/format.js","content":"import { cpCompare } from './parser.js'

function typeOf(node) {
  if (node.kind === 'table') return 'table'
  if (node.kind === 'aot') return 'array'
  if (node.kind === 'array') return 'array'
  return node.kind
}

function toJSON(node, indent) {
  const pad = '  '.repeat(indent)
  const padIn = '  '.repeat(indent + 1)
  if (node.kind === 'table') {
    const keys = Array.from(node.map.keys()).sort(cpCompare)
    if (keys.length === 0) return '{}'
    const parts = keys.map(k => `${padIn}${JSON.stringify(k)}: ${toJSON(node.map.get(k), indent + 1)}`)
    return `{\n${parts.join(',\n')}\n${pad}}`
  }
  if (node.kind === 'aot' || node.kind === 'array') {
    const items = node.items
    if (items.length === 0) return '[]'
    const parts = items.map(it => `${padIn}${toJSON(it, indent + 1)}`)
    return `[\n${parts.join(',\n')}\n${pad}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  if (node.kind === 'integer' || node.kind === 'float') return JSON.stringify(node.value)
  throw new Error(`unknown node kind ${node.kind}`)
}

export function formatJSON(root) {
  return toJSON(root, 0) + '\n'
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    const keys = Array.from(node.map.keys()).sort(cpCompare)
    for (const k of keys) {
      const child = node.map.get(k)
      const p = path === '' ? k : `${path}.${k}`
      out.push(`${p} ${typeOf(child)}`)
      walkKeys(child, p, out)
    }
  } else if (node.kind === 'aot' || node.kind === 'array') {
    const items = node.items
    for (let i = 0; i < items.length; i++) {
      const p = `${path}[${i}]`
      out.push(`${p} ${typeOf(items[i])}`)
      walkKeys(items[i], p, out)
    }
  }
}

export function formatKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.map(l => l + '\n').join('')
}
"}

