{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */
import fs from 'node:fs'
import { parseDocument } from './parser.js'
import { formatJSON, formatKeys } from './format.js'
import { ConfigError } from './errors.js'

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    process.exit(2)
  }
  const mode = args[0]
  let input
  try {
    input = fs.readFileSync(0, 'utf8')
  } catch {
    input = ''
  }
  let root
  try {
    root = parseDocument(input)
  } catch (e) {
    if (e instanceof ConfigError) {
      process.stderr.write(`error: line ${e.line}: ${e.reason}\n`)
      process.exit(2)
    }
    throw e
  }
  const out = mode === 'json' ? formatJSON(root) : formatKeys(root)
  process.stdout.write(out)
  process.exit(0)
}

main()
"}

